const request = $('Research Request').first().json;
const homepage = $('Fetch Homepage').first().json;
const robotsResponse = $('Fetch robots.txt').first().json;
const sitemapResponse = $('Fetch sitemap.xml').first().json;
const canonical = String(request.canonicalUrl || '').trim();
const baseMatch = canonical.match(/^(https?):\/\/([^/?#]+)(?:\/[^?#]*)?/i);
if (!baseMatch) throw new Error('Research request contains an invalid canonical URL');
const baseProtocol = baseMatch[1].toLowerCase();
const baseAuthority = baseMatch[2].toLowerCase();
const origin = baseProtocol + '://' + baseAuthority;
function parseSameOrigin(raw) {
  if (!raw) return null;
  let value = String(raw).replace(/&amp;/g, '&').trim();
  if (!value) return null;
  if (value.startsWith('//')) value = baseProtocol + ':' + value;
  else if (value.startsWith('/')) value = origin + value;
  else if (!/^https?:\/\//i.test(value)) value = origin + '/' + value.replace(/^\.\//, '');
  const match = value.match(/^(https?):\/\/([^/?#]+)([^?#]*)?(?:\?[^#]*)?(?:#.*)?$/i);
  if (!match) return null;
  const protocol = match[1].toLowerCase();
  const authority = match[2].toLowerCase();
  if (protocol !== baseProtocol || authority !== baseAuthority) return null;
  let path = match[3] || '/';
  const parts = [];
  for (const part of path.split('/')) {
    if (!part || part === '.') continue;
    if (part === '..') parts.pop();
    else parts.push(part);
  }
  path = '/' + parts.join('/');
  return { url: origin + path, path };
}
const robotsText = String(robotsResponse.body || '');
const sitemapText = String(sitemapResponse.body || '');
const disallow = [];
let inWildcardAgent = false;
for (const rawLine of robotsText.split(/\r?\n/)) {
  const line = rawLine.replace(/#.*$/, '').trim();
  if (!line) continue;
  const match = line.match(/^([^:]+):\s*(.*)$/);
  if (!match) continue;
  const key = match[1].trim().toLowerCase();
  const value = match[2].trim();
  if (key === 'user-agent') inWildcardAgent = value === '*';
  else if (key === 'disallow' && inWildcardAgent && value) disallow.push(value);
}
const sitemapIndexUrls = [];
const discovered = new Map();
const excludedExtensions = /\.(?:css|js|mjs|map|png|jpe?g|gif|webp|svg|ico|woff2?|ttf|eot|pdf|zip|mp[34]|webm|xml)$/i;
const excludedPaths = /^\/(?:api|_next|assets?|static|cdn-cgi|auth|login|logout|signup|register|dashboard|admin)(?:\/|$)/i;
function addCandidate(raw) {
  const candidate = parseSameOrigin(raw);
  if (!candidate) return;
  if (candidate.path === '/' || excludedExtensions.test(candidate.path) || excludedPaths.test(candidate.path)) return;
  if (disallow.some(rule => candidate.path.startsWith(rule))) return;
  if (!discovered.has(candidate.url)) discovered.set(candidate.url, candidate.path);
}
const homepageHtml = String(homepage.body || '');
for (const match of homepageHtml.matchAll(/\bhref\s*=\s*["']([^"'#]+)["']/gi)) addCandidate(match[1]);
const isSitemapIndex = /<sitemapindex\b/i.test(sitemapText);
const locs = [...sitemapText.matchAll(/<loc>\s*([^<]+?)\s*<\/loc>/gi)].map(m => m[1].trim());
if (isSitemapIndex) {
  for (const loc of locs) {
    const sitemap = parseSameOrigin(loc);
    if (sitemap && /\.xml$/i.test(sitemap.path)) sitemapIndexUrls.push(sitemap.url);
  }
} else {
  for (const loc of locs) addCandidate(loc);
}
const priority = /pricing|price|features?|product|about|how-it-works|integrations?|docs?|documentation|faq|security|use-cases?/i;
const urls = [...discovered.entries()].sort((a,b) => Number(priority.test(b[1])) - Number(priority.test(a[1])) || a[1].length - b[1].length).slice(0,10).map(([url]) => url);
return [{json:{productId:$('Find Registered Product').first().json.id,researchRunId:$('Find Existing Research Run').first().json.id || $('Create Research Run').first().json.id,canonicalUrl:request.canonicalUrl,discoveredUrls:urls,discoveredCount:urls.length,sitemapIndexUrls:[...new Set(sitemapIndexUrls)].slice(0,5),robotsDisallowRules:disallow.slice(0,50),discoveryMethod:'homepage_links_and_root_sitemap',discoveredAt:new Date().toISOString(),robotsHttpStatus:robotsResponse.statusCode ?? null,sitemapHttpStatus:sitemapResponse.statusCode ?? null}}];

const d = $('Discover Internal Pages').first().json;
const r = $('Research Request').first().json;
const m = String(r.canonicalUrl || '').match(/^(https?):\/\/([^/?#]+)/i);
if (!m) throw new Error('Invalid canonical URL');
const origin = m[1].toLowerCase() + '://' + m[2].toLowerCase();
const blocked = Array.isArray(d.robotsDisallowRules) ? d.robotsDisallowRules : [];
const out = [];
for (const raw of (Array.isArray(d.discoveredUrls) ? d.discoveredUrls : []).slice(0,10)) {
 const u = String(raw || '').trim();
 const x = u.match(/^(https?):\/\/([^/?#]+)([^?#]*)(?:\?[^#]*)?(?:#.*)?$/i);
 if (!x) continue;
 const o = x[1].toLowerCase() + '://' + x[2].toLowerCase();
 const p = x[3] || '/';
 if (o !== origin || p === '/' || /\.(css|js|png|jpe?g|gif|svg|ico|woff2?|ttf|pdf|zip|mp[34]|webm|xml)$/i.test(p)) continue;
 if (/^\/(api|_next|assets?|static|auth|login|logout|signup|register|dashboard|admin)(\/|$)/i.test(p) || blocked.some(rule => p.startsWith(rule)) || /[?#]/.test(u)) continue;
 if (!out.some(v => v.sourceUrl === u)) out.push({sourceUrl:u,productId:d.productId,researchRunId:d.researchRunId});
}
const reason = (Array.isArray(d.discoveredUrls) && d.discoveredUrls.length === 0) ? 'no_internal_urls_discovered' : 'no_candidates_passed_revalidation';
return out.length ? out.map(json => ({json})) : [{json:{noValidPages:true,reason}}];

const items = $input.all();
return items.map((item,i) => {
 const d=item.json||{};
 const src=$('Prepare Internal Page Items').all()[i]?.json||{};
 const h=d.headers||{};
 const ct=String(h['content-type']||h['Content-Type']||'').toLowerCase();
 const sc=Number(d.statusCode||0);
 const html=typeof d.body==='string'?d.body:'';
 let status='failed',error='',title='',description='',contentText='';
 if(d.error||(!sc&&d.message)){error=String(d.error?.message||d.message||'HTTP request failed').slice(0,500);}
 else if(sc>=300&&sc<400){status='skipped';error='Redirect not followed; target requires validation';}
 else if(sc<200||sc>=300){error='HTTP '+(sc||'unknown');}
 else if(!/(text\/html|application\/xhtml\+xml)/i.test(ct)){status='skipped';error='Non-HTML content type: '+(ct||'missing');}
 else {
  const dec=s=>String(s||'').replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').replace(/&quot;/gi,'"').replace(/&#39;|&apos;/gi,"'").replace(/&lt;/gi,'<').replace(/&gt;/gi,'>');
  const t=html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  title=dec((t?.[1]||'').replace(/<[^>]+>/g,' ')).replace(/\s+/g,' ').trim().slice(0,500);
  const md=html.match(/<meta[^>]+(?:name|property)=["'](?:description|og:description)["'][^>]+content=["']([^"']*)["']/i)||html.match(/<meta[^>]+content=["']([^"']*)["'][^>]+(?:name|property)=["'](?:description|og:description)["']/i);
  description=dec(md?.[1]||'').replace(/\s+/g,' ').trim().slice(0,2000);
  contentText=dec(html.replace(/<!--[\s\S]*?-->/g,' ').replace(/<(script|style|noscript|svg|template)\b[^>]*>[\s\S]*?<\/\1>/gi,' ').replace(/<\/(p|div|section|article|li|h[1-6]|br|tr)>/gi,'\n').replace(/<[^>]+>/g,' ')).replace(/[\t\r ]+/g,' ').replace(/\n\s*\n+/g,'\n').trim().slice(0,30000);
  if(contentText){status='ready_to_save';}else{status='skipped';error='No extractable HTML text';}
 }
 return {json:{...src,statusCode:sc,contentType:ct,pageStatus:status,error,title,description,contentText,mimeType:ct||null}};
});
